mapper.select:
select v.* FROM (select ln.fin_statement_templet_ln_id, ln.fin_statement_templet_hd_id, ln.line_type, ln.line_seq_number, ln.fin_statement_item_name, ln.fin_statement_item_type, ln.formula_priority,ln.formula_text FROM hls_fin_statement_tmplt_ln ln) v 1 = 1
and v.fin_statement_templet_hd_id = #{finStatementTempletHdId}
and v.line_type = #{lineType}
ORDER BY V.line_seq_number ASC

select v.* FROM (select ln.fin_statement_templet_ln_id, ln.fin_statement_templet_hd_id, ln.line_type, ln.line_seq_number, ln.fin_statement_item_name, ln.fin_statement_item_type, ln.formula_priority,ln.formula_text FROM hls_fin_statement_tmplt_ln ln) v
v.fin_statement_templet_hd_id = #{finStatementTempletHdId}
and v.line_type = #{lineType}
AND v.formula_priority>0
ORDER BY v.formula_priority ASC,v.line_seq_number ASC

select v.*
FROM hls_fin_statement_tmplt_ln  v

		1=1

		and	v.fin_statement_templet_hd_id = #{finStatementTempletHdId}


		and	trim(v.fin_statement_item_name) = #{finStatementItemName}


		and v.line_type = #{lineType}


ORDER BY line_seq_number ASC
